# owner: platform
import unittest

from hourglass.models import Span
from hourglass.gaps import uncovered_labels

OPENING = Span(540, 1020)

# ---
def labels_for(spans):
    return uncovered_labels(spans, OPENING)

class UncoveredLabelTests(unittest.TestCase):
    def test_nobody_working_is_one_gap(self):
        expected = ["gap 09:00-17:00 (480 min)"]
        self.assertEqual(labels_for([]), expected)

    def test_gap_in_the_middle(self):
        spans = [Span(780, 1020), Span(540, 720)]
        expected = ["gap 12:00-13:00 (60 min)"]
        self.assertEqual(labels_for(spans), expected)

    def test_gaps_at_both_ends(self):
        expected = [
            "gap 09:00-10:00 (60 min)",
            "gap 15:00-17:00 (120 min)"
        ]
        spans = [Span(600, 900)]
        self.assertEqual(labels_for(spans), expected)

    def test_touching_spans_leave_no_gap(self):
        spans = [
            Span(540, 700),
            Span(690, 800),
            Span(800, 1020)
        ]
        self.assertEqual(labels_for(spans), [])

    def test_span_matching_opening_hours_has_no_gap(self):
        spans = [Span(540, 600), Span(600, 1020)]
        self.assertEqual(labels_for(spans), [])

    def test_span_before_opening_raises(self):
        with self.assertRaises(ValueError):
            labels_for([Span(500, 600)])

    def test_span_after_closing_raises(self):
        with self.assertRaises(ValueError):
            labels_for([Span(900, 1100)])
